    <script>
(() => {
 const buttons = document.querySelectorAll('[data-faction]');
 function select(button) {
  buttons.forEach(item => {
   const active = item === button;
   item.classList.toggle('active', active);
   item.setAttribute('aria-pressed', String(active));
   document.getElementById(item.dataset.faction).style.display = active ? 'block' : 'none';
  });
 }
 buttons.forEach(button => {
  button.type = 'button';
  button.setAttribute('aria-controls', button.dataset.faction);
  button.addEventListener('click', () => select(button));
 });
 if (buttons.length) select(buttons[0]);
})();
</script>
<dialog id="wi-viewer" aria-label="<?= $_SESSION['lang'] === 'ru' ? 'Просмотр изображения' : 'Image viewer' ?>"><button type="button" id="wi-close" aria-label="<?= $_SESSION['lang'] === 'ru' ? 'Закрыть' : 'Close' ?>">×</button><button type="button" id="wi-prev" aria-label="<?= $_SESSION['lang'] === 'ru' ? 'Предыдущее' : 'Previous' ?>">‹</button><figure><img id="wi-full" alt=""><figcaption id="wi-caption"></figcaption></figure><button type="button" id="wi-next" aria-label="<?= $_SESSION['lang'] === 'ru' ? 'Следующее' : 'Next' ?>">›</button></dialog>
<script>
(() => {
 const modal=document.getElementById('wi-viewer');
 const all=[...document.querySelectorAll('.be-card .wi-zoom')];
 let group=[],index=0,opener=null,overflow='';
 function show(i){index=(i+group.length)%group.length;const img=group[index].querySelector('img');const full=document.getElementById('wi-full');full.src=img.src;full.alt=img.alt;document.getElementById('wi-caption').textContent=img.alt+' · '+(index+1)+' / '+group.length;}
 all.forEach(button=>button.addEventListener('click',()=>{opener=button;group=all.filter(item=>!!item.closest('.be-card')===!!button.closest('.be-card'));show(group.indexOf(button));overflow=document.body.style.overflow;modal.showModal();document.body.style.overflow='hidden';document.getElementById('wi-close').focus();}));
 document.getElementById('wi-close').addEventListener('click',()=>modal.close());
 document.getElementById('wi-prev').addEventListener('click',()=>show(index-1));
 document.getElementById('wi-next').addEventListener('click',()=>show(index+1));
 modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});
 modal.addEventListener('close',()=>{document.body.style.overflow=overflow;opener?.focus();});
 modal.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1));}});
})();
</script>
</body>
